/**
 * Self-contained HTML rendering of `atl.report/v1` (04 §9.4): inline CSS and SVG, no scripts, no external fonts or
 * images; `@media print` for A4. The share copy (§9.5) is the same renderer over a redacted report with a banner.
 * Every value is escaped; the chart SVG is generated by `charts.ts` from numbers only.
 *
 * Languages (09-i18n-and-visual.md §1.8, I1/I5): the page texts exist in ja / en / zh-CN. Without `lang` the document
 * holds one block per language — Japanese shown by default, `#en` / `#zh-CN` (`:target`, no script: the CSP forbids
 * scripts) switch, with language links at the top — the same layout as the web share renderer (render-share.mjs).
 * Values that come from the report itself (card and step titles, check names, reasons) stay as recorded (zh-CN source).
 */
import { escapeXml } from './charts.js';
import type { Report } from './report.js';

export type ReportLang = 'ja' | 'en' | 'zh-CN';
/** The languages of a document without `lang`; the first one is shown by default (I1). */
export const REPORT_LANGS: readonly ReportLang[] = ['ja', 'en', 'zh-CN'];
const LANG_NAME: Record<ReportLang, string> = { ja: '日本語', en: 'English', 'zh-CN': '中文' };

const str = (v: unknown): string => (v === undefined || v === null ? '—' : typeof v === 'string' ? v : JSON.stringify(v));
const esc = (v: unknown): string => escapeXml(str(v));

interface Labels {
  state: Record<string, string>;
  attempt: Record<string, string>;
  result: Record<string, string>;
  badgeLevel: Record<string, string>;
  badgeStatus: Record<string, string>;
  role: Record<string, string>;
  title: string;
  banner: string;
  header: (rev: number, at: string, version: string, variant: string) => string;
  summary: string;
  outcome: string;
  badge: (title: string, level: string, score: string) => string;
  holder: string;
  time: string;
  timeValue: (total: number, active: number) => string;
  checks: string;
  checksValue: (auto: number, manual: number, failed: number, drift: number) => string;
  trust: string;
  trustValue: (h: number, m: number, l: number) => string;
  session: string;
  sessionValue: (region: string, account: string, reason: string) => string;
  reused: string;
  arch: string;
  startProfile: string;
  provisionCols: [string, string, string];
  steps: string;
  checkCols: [string, string, string, string, string];
  inherited: string;
  lateOwnership: string;
  manual: string;
  experiments: string;
  noExperiments: string;
  variantCols: [string, string, string];
  noRecord: string;
  comparable: string;
  notComparable: (reasons: string) => string;
  acrossTypes: string;
  quiz: string;
  quizValue: (best: string, attempts: number) => string;
  cost: string;
  quote: string;
  costCols: [string, string, string, string];
  cleanup: string;
  cleanupValue: (status: string, n: number) => string;
  manualCols: [string, string, string, string];
  cleanupVerify: string;
  certificate: string;
  certificateValue: (id: string, url: string) => string;
  appendix: string;
  historyCols: [string, string, string, string, string];
  digests: (catalog: string, content: string, digest: string) => string;
  disclaimer: string;
  shareExpiry: string;
  colon: string;
  sep: string;
}

